// Parse Payment Message with Regex
const input = $input.item.json;
const message = input.message;
const text = message.text || '';
const lines = text.split('\n').map(l => l.trim()).filter(l => l);

// Структура ожидаемого сообщения:
// 26.01
// МП (объект)
// Горничная (должность)
// Иванова Юлия 11 (ФИО часы)
// Каратова Самара 8

const result = {
  workDate: null,
  objectLocation: null,
  position: null,
  employees: [],
  parseErrors: [],
  isValid: false
};

// Парсим дату (первая строка)
const dateMatch = lines[0]?.match(/^(\d{1,2})\.(\d{1,2})(?:\.(\d{2,4}))?$/);
if (dateMatch) {
  const day = dateMatch[1].padStart(2, '0');
  const month = dateMatch[2].padStart(2, '0');
  const year = dateMatch[3] || new Date().getFullYear();
  result.workDate = `${year}-${month}-${day}`;
} else {
  result.parseErrors.push('Не удалось распознать дату в первой строке');
}

// Парсим объект (вторая строка)
if (lines[1]) {
  result.objectLocation = lines[1];
} else {
  result.parseErrors.push('Не указан объект');
}

// Парсим должность (третья строка)
if (lines[2]) {
  result.position = lines[2];
} else {
  result.parseErrors.push('Не указана должность');
}

// Парсим сотрудников (остальные строки)
// Формат: ФИО часы
// Примеры: "Иванова Юлия 11", "Петров И.И. 8"
for (let i = 3; i < lines.length; i++) {
  const line = lines[i];

  // Попытка 1: ФИО пробел число
  const match1 = line.match(/^([А-Яа-яЁё\s\.]+)\s+(\d+(?:\.\d+)?)$/);
  if (match1) {
    result.employees.push({
      fullName: match1[1].trim(),
      hours: parseFloat(match1[2])
    });
    continue;
  }

  // Попытка 2: число в начале ("8 Иванова Юлия")
  const match2 = line.match(/^(\d+(?:\.\d+)?)\s+([А-Яа-яЁё\s\.]+)$/);
  if (match2) {
    result.employees.push({
      fullName: match2[2].trim(),
      hours: parseFloat(match2[1])
    });
    continue;
  }

  // Попытка 3: разделитель "-" или ":"
  const match3 = line.match(/^([А-Яа-яЁё\s\.]+)[\-:]\s*(\d+(?:\.\d+)?)$/);
  if (match3) {
    result.employees.push({
      fullName: match3[1].trim(),
      hours: parseFloat(match3[2])
    });
    continue;
  }

  // Строка не распознана
  if (line.length > 2) {
    result.parseErrors.push(`Не распознана строка: "${line}"`);
  }
}

// Валидация
result.isValid = result.workDate && 
                  result.objectLocation && 
                  result.position && 
                  result.employees.length > 0;

return {
  json: {
    message,
    parsed: result,
    chatId: message.chat.id,
    userId: message.from.id,
    username: message.from.username
  }
};

// Build error message
const input = $input.item.json;
const errors = input.parsed.parseErrors;

let errorMessage = '❌ *Ошибка разбора сообщения*\n\n';

if (errors.length > 0) {
  errorMessage += '*Проблемы:*\n';
  errors.forEach(e => {
    errorMessage += `• ${e}\n`;
  });
}

errorMessage += '\n*Ожидаемый формат:*\n';
errorMessage += '```\n';
errorMessage += '26.01\n';
errorMessage += 'МП\n';
errorMessage += 'Горничная\n';
errorMessage += 'Иванова Юлия 11\n';
errorMessage += 'Петрова Мария 8\n';
errorMessage += '```';

return {
  json: {
    ...input,
    errorMessage
  }
};

// Prepare batch insert records
const input = $input.item.json;
const parsed = input.parsed;
const message = input.message;

// Формируем массив записей для batch insert
const records = parsed.employees.map(emp => ({
  work_date: parsed.workDate,
  object_location: parsed.objectLocation,
  position: parsed.position,
  full_name: emp.fullName,
  hours: emp.hours,
  telegram_user_id: message.from.id,
  telegram_username: message.from.username,
  telegram_chat_id: message.chat.id,
  telegram_message_id: message.message_id
}));

return {
  json: {
    records,
    summary: {
      date: parsed.workDate,
      object: parsed.objectLocation,
      position: parsed.position,
      employeesCount: records.length,
      totalHours: records.reduce((sum, r) => sum + r.hours, 0)
    },
    message,
    chatId: input.chatId
  }
};

// Build confirmation message
const prepareData = $('Prepare Batch Insert').item.json;
const summary = prepareData.summary;
const linkResult = $input.item.json;

// Форматируем дату
const date = new Date(summary.date);
const dateFormatted = date.toLocaleDateString('ru-RU', {
  day: 'numeric',
  month: 'long'
});

let confirmMessage = '✅ *Оплата записана*\n\n';
confirmMessage += `📅 *Дата:* ${dateFormatted}\n`;
confirmMessage += `📍 *Объект:* ${summary.object}\n`;
confirmMessage += `💼 *Должность:* ${summary.position}\n\n`;
confirmMessage += `👥 *Сотрудников:* ${summary.employeesCount}\n`;
confirmMessage += `⏱ *Всего часов:* ${summary.totalHours}\n`;

// Список сотрудников
confirmMessage += '\n*Записи:*\n';
prepareData.records.forEach((r, i) => {
  confirmMessage += `${i + 1}. ${r.full_name} — ${r.hours} ч.\n`;
});

confirmMessage += '\n_Записи автоматически связаны с кандидатами (если найдены)_';

return {
  json: {
    confirmMessage,
    chatId: prepareData.chatId,
    messageId: prepareData.message.message_id
  }
};
